import{_ as o,C as a,o as d,c as n,j as e,a as i,E as l,al as s}from"./chunks/framework.7vp1BMOE.js";const h="/px4_user_guide/assets/nwblue_pro-h757.B51eKUgl.png",P=JSON.parse('{"title":"NWBlue Pro H757","description":"","frontmatter":{},"headers":[],"relativePath":"en/flight_controller/nwblue_pro-h757.md","filePath":"en/flight_controller/nwblue_pro-h757.md"}'),c={name:"en/flight_controller/nwblue_pro-h757.md"};function u(p,t,b,m,g,f){const r=a("Badge");return d(),n("div",null,[t[0]||(t[0]=e("h1",{id:"nwblue-pro-h757",tabindex:"-1"},[i("NWBlue Pro H757 "),e("a",{class:"header-anchor",href:"#nwblue-pro-h757","aria-label":'Permalink to "NWBlue Pro H757"'},"​")],-1)),l(r,{type:"tip",text:"PX4 v1.18"}),t[1]||(t[1]=s('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 does not manufacture this (or any) autopilot. Contact the manufacturer for hardware support or compliance issues.</p></div><p>The <em>NWBlue Pro H757</em> is a 36 x 36 mm FPV flight controller built around a <a href="https://docs.cubepilot.org/user-guides/cubenode/pin-descriptions" target="_blank" rel="noreferrer">CubePilot CubeNode H757</a> module carrying an STM32H757 microcontroller.</p><p><img src="'+h+'" alt="NWBlue Pro H757"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This flight controller is <a href="./../flight_controller/autopilot_manufacturer_supported">manufacturer supported</a>.</p></div><h2 id="store" tabindex="-1">Where to Buy <a class="header-anchor" href="#store" aria-label="Permalink to &quot;Where to Buy {#store}&quot;">​</a></h2><p>Order from <a href="https://nwblue.com/products/pro-h757-fpv-flight-controller" target="_blank" rel="noreferrer">NWBlue</a> (US).</p><h2 id="specifications" tabindex="-1">Specifications <a class="header-anchor" href="#specifications" aria-label="Permalink to &quot;Specifications {#specifications}&quot;">​</a></h2><ul><li><strong>Processor</strong><ul><li><strong>Main FMU processor:</strong> STM32H757 (32-bit Arm® Cortex®-M7 at 480 MHz, 2 MB Flash, 1 MB RAM), on a CubePilot CubeNode module</li></ul></li><li><strong>Sensors</strong><ul><li><strong>IMU:</strong> <a href="https://invensense.tdk.com/products/motion-tracking/6-axis/icm-45686/" target="_blank" rel="noreferrer">InvenSense ICM-45686</a> (SPI3, inside the CubeNode module)</li><li><strong>Barometer:</strong> <a href="https://www.infineon.com/part/DPS368" target="_blank" rel="noreferrer">Infineon DPS368</a> (SPI3)</li><li><strong>Magnetometer:</strong> <a href="https://www.st.com/en/mems-and-sensors/iis2mdc.html" target="_blank" rel="noreferrer">ST IIS2MDC</a> (I2C3, internal)</li></ul></li><li><strong>Interfaces</strong><ul><li><strong>PWM outputs:</strong> 9, <a href="./../peripherals/dshot">DShot</a> and <a href="./../peripherals/dshot#bidirectional-dshot-telemetry">Bidirectional DShot</a> capable</li><li><strong>Serial ports:</strong> 6 (<code>TELEM1</code>, <code>TELEM2</code>, <code>TELEM3</code>, <code>GPS1</code>, <code>RC</code>, and a spare receive-only port on the VTX connector)</li><li><strong>I2C buses:</strong> 1 external (on the <code>GPS</code> connector, for an external compass) and 1 internal (magnetometer)</li><li><strong>CAN buses:</strong> 1 (<a href="./../dronecan/">DroneCAN</a>)</li><li><strong>USB:</strong> USB-C</li><li><strong>RC input:</strong> Yes, on a dedicated <code>RC</code> connector</li><li><strong>SD card:</strong> MicroSD slot (SDMMC2)</li><li><strong>Other:</strong> buzzer output (external components required), RGB status LED, SWD</li></ul></li><li><strong>Electrical data</strong><ul><li><strong>Input voltage:</strong> 4S to 12S LiPo on the <code>ESC</code> connector (<code>VBAT</code>)</li><li><strong>5 V output:</strong> 3.5 A, current limited, shared by the <code>RC</code>, <code>GPS</code>, <code>TELEM</code> and <code>CAN</code> connectors</li><li><strong>10 V / 12 V output:</strong> 3.5 A, on the <code>VTX</code> and <code>Power Out</code> connectors</li><li><strong>Power monitoring:</strong> battery voltage through an onboard 21:1 divider; battery current from an external current sensor wired to the <code>ESC</code> connector</li></ul></li><li><strong>Mechanical data</strong><ul><li><strong>Dimensions:</strong> 36 x 36 x 18 mm (including connectors)</li><li><strong>Mounting pattern:</strong> 30.5 x 30.5 mm</li></ul></li></ul><h2 id="manufacturer-documentation" tabindex="-1">Manufacturer Documentation <a class="header-anchor" href="#manufacturer-documentation" aria-label="Permalink to &quot;Manufacturer Documentation&quot;">​</a></h2><p>Connector pinouts, wiring diagrams and mechanical drawings are in the <a href="https://docs.nwblue.com/nw-blue/products/autopilots/proh757/overview" target="_blank" rel="noreferrer">NWBlue Pro H757 documentation</a>. 3D models are available on the <a href="https://docs.nwblue.com/nw-blue/products/autopilots/proh757/3d-models" target="_blank" rel="noreferrer">3D Models</a> page.</p><h2 id="building-firmware" tabindex="-1">Building Firmware <a class="header-anchor" href="#building-firmware" aria-label="Permalink to &quot;Building Firmware&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Most users will not need to build this firmware. It is pre-built and automatically installed by <em>QGroundControl</em> when appropriate hardware is connected.</p></div><p>To <a href="./../dev_setup/building_px4">build PX4</a> for this target from source:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nwblue_pro-h757_default</span></span></code></pre></div><h2 id="radio_control" tabindex="-1">Radio Control <a class="header-anchor" href="#radio_control" aria-label="Permalink to &quot;Radio Control {#radio_control}&quot;">​</a></h2><p>A remote control (RC) radio system is required if you want to <em>manually</em> control your vehicle (PX4 does not require a radio system for autonomous flight modes).</p><p>You will need to <a href="./../getting_started/rc_transmitter_receiver">select a compatible transmitter/receiver</a> and then <em>bind</em> them so that they communicate (read the instructions that come with your specific transmitter/receiver).</p><p>The <code>RC</code> connector is wired directly to the FMU (UART4) and powered from the 5 V rail. PX4 autodetects receivers on this port that use S.BUS, S.BUS2, Spektrum DSM / DSM2 / DSM-X, Yuneec ST24, Graupner SUMD, CRSF, or GHST. PPM is not supported: the RC pins have no capture channel on the timer that PX4 uses for PPM decoding.</p><p>Both TX and RX are broken out, so CRSF and GHST telemetry back to the transmitter works over the same cable.</p><h2 id="gps_compass" tabindex="-1">GPS &amp; Compass <a class="header-anchor" href="#gps_compass" aria-label="Permalink to &quot;GPS &amp; Compass {#gps_compass}&quot;">​</a></h2><p>The <code>GPS</code> connector carries <code>GPS1</code> (UART8) together with the external I2C bus for a compass. The module should be <a href="./../assembly/mount_gps_compass">mounted on the frame</a> as far away from other electronics as possible, with the direction marker pointing towards the front of the vehicle.</p><h2 id="pinout" tabindex="-1">Pinout <a class="header-anchor" href="#pinout" aria-label="Permalink to &quot;Pinout&quot;">​</a></h2><p>The full pinout with connector locations is on the <a href="https://docs.nwblue.com/nw-blue/products/autopilots/proh757/pinout" target="_blank" rel="noreferrer">manufacturer&#39;s pinout page</a>.</p><h3 id="esc" tabindex="-1">ESC <a class="header-anchor" href="#esc" aria-label="Permalink to &quot;ESC&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th></tr></thead><tbody><tr><td>1</td><td>VBAT in (4S to 12S)</td></tr><tr><td>2</td><td>GND</td></tr><tr><td>3</td><td>Current sense</td></tr><tr><td>4</td><td>ESC telemetry (USART1 RX)</td></tr><tr><td>5</td><td>Output 1</td></tr><tr><td>6</td><td>Output 2</td></tr><tr><td>7</td><td>Output 3</td></tr><tr><td>8</td><td>Output 4</td></tr></tbody></table><h3 id="pwm-aux" tabindex="-1">PWM AUX <a class="header-anchor" href="#pwm-aux" aria-label="Permalink to &quot;PWM AUX&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th></tr></thead><tbody><tr><td>1</td><td>Output 5</td></tr><tr><td>2</td><td>Output 6</td></tr><tr><td>3</td><td>Output 7</td></tr><tr><td>4</td><td>Output 8</td></tr><tr><td>5</td><td>Output 9</td></tr><tr><td>6</td><td>GND</td></tr></tbody></table><h3 id="rc-uart4" tabindex="-1">RC (UART4) <a class="header-anchor" href="#rc-uart4" aria-label="Permalink to &quot;RC (UART4)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th></tr></thead><tbody><tr><td>1</td><td>5V</td></tr><tr><td>2</td><td>TX</td></tr><tr><td>3</td><td>RX</td></tr><tr><td>4</td><td>GND</td></tr></tbody></table><h3 id="gps-uart8" tabindex="-1">GPS (UART8) <a class="header-anchor" href="#gps-uart8" aria-label="Permalink to &quot;GPS (UART8)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th></tr></thead><tbody><tr><td>1</td><td>5V</td></tr><tr><td>2</td><td>TX</td></tr><tr><td>3</td><td>RX</td></tr><tr><td>4</td><td>SCL</td></tr><tr><td>5</td><td>SDA</td></tr><tr><td>6</td><td>GND</td></tr></tbody></table><h3 id="telem1-uart7" tabindex="-1">TELEM1 (UART7) <a class="header-anchor" href="#telem1-uart7" aria-label="Permalink to &quot;TELEM1 (UART7)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th></tr></thead><tbody><tr><td>1</td><td>5V</td></tr><tr><td>2</td><td>TX</td></tr><tr><td>3</td><td>RX</td></tr><tr><td>4</td><td>NC</td></tr><tr><td>5</td><td>NC</td></tr><tr><td>6</td><td>GND</td></tr></tbody></table><h3 id="vtx-usart6" tabindex="-1">VTX (USART6) <a class="header-anchor" href="#vtx-usart6" aria-label="Permalink to &quot;VTX (USART6)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th></tr></thead><tbody><tr><td>1</td><td>10V / 12V</td></tr><tr><td>2</td><td>GND</td></tr><tr><td>3</td><td>TX (USART6)</td></tr><tr><td>4</td><td>RX (USART6)</td></tr><tr><td>5</td><td>RX (USART2)</td></tr><tr><td>6</td><td>GND</td></tr></tbody></table><h3 id="can" tabindex="-1">CAN <a class="header-anchor" href="#can" aria-label="Permalink to &quot;CAN&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th></tr></thead><tbody><tr><td>1</td><td>5V</td></tr><tr><td>2</td><td>CAN_H</td></tr><tr><td>3</td><td>CAN_L</td></tr><tr><td>4</td><td>GND</td></tr></tbody></table><h3 id="power-out" tabindex="-1">Power Out <a class="header-anchor" href="#power-out" aria-label="Permalink to &quot;Power Out&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th></tr></thead><tbody><tr><td>1</td><td>VBAT out</td></tr><tr><td>2</td><td>GND</td></tr><tr><td>3</td><td>10V / 12V</td></tr></tbody></table><h3 id="swd" tabindex="-1">SWD <a class="header-anchor" href="#swd" aria-label="Permalink to &quot;SWD&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th></tr></thead><tbody><tr><td>1</td><td>3.3V</td></tr><tr><td>2</td><td>SWDIO</td></tr><tr><td>3</td><td>SWCLK</td></tr><tr><td>4</td><td>GND</td></tr></tbody></table><h2 id="serial-port-mapping" tabindex="-1">Serial Port Mapping <a class="header-anchor" href="#serial-port-mapping" aria-label="Permalink to &quot;Serial Port Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>Device</th><th>PX4 Default</th><th>Connector</th><th>Pins (TX / RX)</th></tr></thead><tbody><tr><td>USART1</td><td>/dev/ttyS0</td><td>TEL3</td><td>ESC</td><td>— / PB7</td></tr><tr><td>USART2</td><td>/dev/ttyS1</td><td>—</td><td>VTX</td><td>— / PA3</td></tr><tr><td>UART4</td><td>/dev/ttyS2</td><td>RC</td><td>RC</td><td>PA0 / PB8</td></tr><tr><td>USART6</td><td>/dev/ttyS3</td><td>TEL2</td><td>VTX</td><td>PC6 / PC7</td></tr><tr><td>UART7</td><td>/dev/ttyS4</td><td>TEL1</td><td>TELEM1</td><td>PE8 / PE7</td></tr><tr><td>UART8</td><td>/dev/ttyS5</td><td>GPS1</td><td>GPS</td><td>PE1 / PE0</td></tr></tbody></table><p>No port has flow control. USART1 and USART2 are receive-only: only the RX pin is broken out.</p><p>TEL3 is the ESC telemetry input and is configured for it by default (<a href="./../advanced_config/parameter_reference#DSHOT_TEL_CFG">DSHOT_TEL_CFG</a> = <code>103</code>).</p><h2 id="pwm-outputs" tabindex="-1">PWM Outputs <a class="header-anchor" href="#pwm-outputs" aria-label="Permalink to &quot;PWM Outputs&quot;">​</a></h2><p>The board provides 9 PWM outputs, all of which support <a href="./../peripherals/dshot">DShot</a>. Outputs 1 to 4 are on the <code>ESC</code> connector, outputs 5 to 9 on the <code>PWM AUX</code> connector.</p><p>The outputs are split across 4 timer groups:</p><table tabindex="0"><thead><tr><th>Outputs</th><th>Timer</th></tr></thead><tbody><tr><td>1, 2, 3, 4</td><td>Timer1</td></tr><tr><td>5, 6</td><td>Timer4</td></tr><tr><td>7, 8</td><td>Timer3</td></tr><tr><td>9</td><td>Timer2</td></tr></tbody></table><p>All outputs within the same group must use the same protocol and update rate.</p><p><a href="./../peripherals/dshot#bidirectional-dshot-telemetry">Bidirectional DShot</a> works on every output except output 6. That output is TIM4_CH4, and the STM32H7 DMAMUX has no request line for it, so the capture DMA needed for the ESC response cannot be set up. Use output 6 for plain DShot or PWM.</p><h2 id="osd" tabindex="-1">OSD <a class="header-anchor" href="#osd" aria-label="Permalink to &quot;OSD&quot;">​</a></h2><p>There is no analog OSD chip on this board, so analog video cannot be overlaid. An HD VTX can render the OSD itself over MSP DisplayPort: connect it to the VTX connector (USART6, TEL2) and set <a href="./../advanced_config/parameter_reference#MSP_OSD_CONFIG">MSP_OSD_CONFIG</a> to <code>102</code>. See <a href="./../peripherals/osd">OSD</a> for details.</p><p>The port is not claimed by default, so it can be used for MAVLink or any other protocol instead.</p><h2 id="battery-monitoring" tabindex="-1">Battery Monitoring <a class="header-anchor" href="#battery-monitoring" aria-label="Permalink to &quot;Battery Monitoring&quot;">​</a></h2><p>The board is powered from the <code>ESC</code> connector. The voltage divider is set by default (<a href="./../advanced_config/parameter_reference#BAT1_V_DIV">BAT1_V_DIV</a> = <code>21.0</code>).</p><p>Current sensing is fed from the ESC connector, so <a href="./../advanced_config/parameter_reference#BAT1_A_PER_V">BAT1_A_PER_V</a> depends on the current sensor in use and has to be <a href="./../config/battery">calibrated</a>.</p><h2 id="debug-port" tabindex="-1">Debug Port <a class="header-anchor" href="#debug-port" aria-label="Permalink to &quot;Debug Port&quot;">​</a></h2><p>There is no dedicated debug UART. The system console and MAVLink both run over USB. SWD is broken out for use with a debugger.</p><p><a id="bootloader"></a></p><h2 id="px4-bootloader-update" tabindex="-1">PX4 Bootloader Update <a class="header-anchor" href="#px4-bootloader-update" aria-label="Permalink to &quot;PX4 Bootloader Update&quot;">​</a></h2><p>Boards that ship without the PX4 bootloader must have it flashed before PX4 firmware can be installed. Download the <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/nwblue/pro-h757/extras/nwblue_pro-h757_bootloader.bin" target="_blank" rel="noreferrer">nwblue_pro-h757_bootloader.bin</a> bootloader binary and follow the <a href="./../advanced_config/bootloader_update_from_betaflight#dfu-bootloader-update">DFU Bootloader Update</a> instructions.</p><p>Once the PX4 bootloader is flashed, firmware can be installed normally via <em>QGroundControl</em>.</p>',63))])}const T=o(c,[["render",u]]);export{P as __pageData,T as default};
